//! 🔢️ Exact IEEE words across owned DSL, pack and field-width boundaries.
use crate::os_dsl::{self,DslField,FieldSpec,FieldValue,JoinMode,Number,ParseOptions,RecordLayout,RecordSpec,RecordValue,Shape,DslValue};
use crate::os_pack::{self,EncodeOptions,DecodeOptions};
fn corpus()->serde_json::Value{serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap()}
fn words64()->Vec<u64>{corpus()["binary64Bits"].as_array().unwrap().iter().map(|value|u64::from_str_radix(value.as_str().unwrap(),16).unwrap()).collect()}
fn words32()->Vec<u32>{corpus()["binary32Bits"].as_array().unwrap().iter().map(|value|u32::from_str_radix(value.as_str().unwrap(),16).unwrap()).collect()}
fn float(value:&FieldValue)->f64{match value{FieldValue::Float(value)=>*value,_=>panic!("expected owned float")}}
fn spec()->RecordSpec{RecordSpec::new(None,RecordLayout::Lines,vec![FieldSpec::new(1,"value",Shape::Float),FieldSpec::new(2,"values",Shape::List(Box::new(Shape::Float)))])}
fn record(words:&[u64])->RecordValue{let mut record=RecordValue::default();record.fields.insert(1,FieldValue::Float(f64::from_bits(words[0])));record.fields.insert(2,FieldValue::List(words.iter().map(|word|FieldValue::Float(f64::from_bits(*word))).collect()));record}
fn assert_record(value:&RecordValue,words:&[u64]){assert_eq!(float(value.get(1).unwrap()).to_bits(),words[0]);let FieldValue::List(values)=value.get(2).unwrap()else{panic!("expected float list")};assert_eq!(values.iter().map(|value|float(value).to_bits()).collect::<Vec<_>>(),words);}
#[test]
fn ieee_payload_native_literal_words_are_exact_at_both_widths(){let data=corpus();for word in words64(){let value=f64::from_bits(word);let text=os_dsl::format_f64(value);assert_eq!(os_dsl::parse_f64(&text).unwrap().to_bits(),word);if value.is_nan(){assert_eq!(text,format!("{}{:016x}",data["binary64NanPrefix"].as_str().unwrap(),word));}}for word in words32(){let value=f32::from_bits(word);let text=os_dsl::format_f32(value);assert_eq!(os_dsl::parse_f32(&text).unwrap().to_bits(),word);if value.is_nan(){assert_eq!(text,format!("{}{:08x}",data["binary32NanPrefix"].as_str().unwrap(),word));}}for text in data["invalid64"].as_array().unwrap(){assert!(os_dsl::parse_f64(text.as_str().unwrap()).is_err());}for text in data["invalid32"].as_array().unwrap(){assert!(os_dsl::parse_f32(text.as_str().unwrap()).is_err());}}
#[test]
fn ieee_payload_scalar_and_packed_lists_preserve_every_word(){let words=words64();for &word in &words{let mut rotated=words.clone();rotated[0]=word;let input=record(&rotated);let bytes=os_pack::encode_document(&spec(),&input,&EncodeOptions::default()).unwrap();let(restored,_)=os_pack::decode_document(&bytes,&spec(),&DecodeOptions::default()).unwrap();assert_record(&restored,&rotated);let body=os_pack::encode_record_body(&spec(),&input,&EncodeOptions::default()).unwrap();let(restored,_)=os_pack::decode_record_body(&body,&spec(),&DecodeOptions::default()).unwrap();assert_record(&restored,&rotated);}}
#[test]
fn ieee_payload_dsl_scalar_and_numeric_list_preserve_every_word(){let words=words64();for &word in &words{let mut rotated=words.clone();rotated[0]=word;let input=record(&rotated);let text=os_dsl::print(&input,&spec(),JoinMode::Document);assert_record(&os_dsl::parse(&text,&spec(),&ParseOptions::default()).unwrap(),&rotated);}}
#[test]
fn ieee_payload_generic_value_preserves_every_word(){let spec=RecordSpec::new(None,RecordLayout::Inline,vec![FieldSpec::new(1,"value",Shape::Value)]);for word in words64(){let mut input=RecordValue::default();input.fields.insert(1,FieldValue::Value(DslValue::Number(Number::Float(f64::from_bits(word)))));let bytes=os_pack::encode_document(&spec,&input,&EncodeOptions::default()).unwrap();let(restored,_)=os_pack::decode_document(&bytes,&spec,&DecodeOptions::default()).unwrap();let FieldValue::Value(DslValue::Number(Number::Float(value)))=restored.get(1).unwrap()else{panic!("expected generic float")};assert_eq!(value.to_bits(),word);let text=os_dsl::print(&input,&spec,JoinMode::Document);let restored=os_dsl::parse(&text,&spec,&ParseOptions::default()).unwrap();let FieldValue::Value(DslValue::Number(Number::Float(value)))=restored.get(1).unwrap()else{panic!("expected generic float")};assert_eq!(value.to_bits(),word);}}
#[test]
fn ieee_payload_binary32_field_conversion_preserves_signaling_payloads(){for word in words32(){let value=f32::from_bits(word);let encoded=<f32 as DslField>::to_value(&value);assert_eq!(<f32 as DslField>::from_value(&encoded).unwrap().to_bits(),word);let spec=RecordSpec::new(None,RecordLayout::Inline,vec![FieldSpec::new(1,"value",<f32 as DslField>::shape())]);let mut input=RecordValue::default();input.fields.insert(1,encoded);let bytes=os_pack::encode_document(&spec,&input,&EncodeOptions::default()).unwrap();let(restored,_)=os_pack::decode_document(&bytes,&spec,&DecodeOptions::default()).unwrap();assert_eq!(<f32 as DslField>::from_value(restored.get(1).unwrap()).unwrap().to_bits(),word);let text=os_dsl::print(&input,&spec,JoinMode::Document);let restored=os_dsl::parse(&text,&spec,&ParseOptions::default()).unwrap();assert_eq!(<f32 as DslField>::from_value(restored.get(1).unwrap()).unwrap().to_bits(),word);}}

fn oracle(body:&[u8],words:&[u64]){use std::{io::Write,process::{Command,Stdio}};let expected=serde_json::to_string(&words.iter().map(|word|format!("{word:016x}")).collect::<Vec<_>>()).unwrap();let script=r#"import assert from 'node:assert/strict';import{Database}from'bun:sqlite';const words=__WORDS__.map(value=>BigInt('0x'+value));const bytes=new Uint8Array(await Bun.stdin.arrayBuffer()),view=new DataView(bytes.buffer);let offset=0;function integer(){let value=0,shift=0;for(;;){const byte=bytes[offset++];assert.ok(byte!==undefined);value+=(byte&127)*2**shift;if(!(byte&128))return value;shift+=7;assert.ok(shift<53)}}function word(expected){assert.equal(view.getBigUint64(offset,true),expected);offset+=8}assert.equal(integer(),0);const count=integer();if(count===2){assert.equal(integer(),1);assert.equal(bytes[offset++],5);word(words[0]);assert.equal(integer(),2);assert.equal(bytes[offset++],21);assert.equal(integer(),words.length);for(const expected of words)word(expected)}else{assert.equal(count,1);assert.equal(integer(),1);assert.equal(bytes[offset++],20);assert.equal(integer(),words.length);assert.equal(integer(),1);assert.equal(integer(),1);assert.equal(bytes[offset++],0);assert.equal(bytes[offset++],4);for(const expected of words)word(expected)}assert.equal(offset,bytes.length);const db=new Database(':memory:');db.run('CREATE TABLE exact_word(ordinal INTEGER PRIMARY KEY,word BLOB NOT NULL CHECK(length(word)=8))');for(let index=0;index<words.length;index++){const raw=new Uint8Array(8);new DataView(raw.buffer).setBigUint64(0,words[index],true);db.run('INSERT INTO exact_word VALUES(?,?)',index,raw)}assert.equal(db.query('PRAGMA integrity_check').get().integrity_check,'ok');for(const row of db.query('SELECT ordinal,word FROM exact_word ORDER BY ordinal').all()){assert.equal(new DataView(row.word.buffer,row.word.byteOffset,row.word.byteLength).getBigUint64(0,true),words[row.ordinal])}db.close();await Bun.write(Bun.stdout,bytes);"#.replace("__WORDS__",&expected);let mut child=Command::new("bun").args(["-e",&script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(body).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));assert_eq!(output.stdout,body);}
fn row_spec()->RecordSpec{RecordSpec::new(None,RecordLayout::Inline,vec![FieldSpec::new(1,"value",Shape::Float)])}
fn row_spec_controlled<C:os_dsl::NativeSchemaControl>(control:&mut C)->Result<RecordSpec,String>{control.scoped_stage(|control|{control.begin_stage(1)?;let mut fields=control.allocate_vec(1)?;fields.push(os_dsl::schema::producer::field(1,"value",Shape::Float,control)?);control.step()?;os_dsl::schema::producer::record(None,RecordLayout::Inline,fields,control)})}
fn row_spec_producer()->os_dsl::RecordSpecProducer{os_dsl::RecordSpecProducer{ordinary:row_spec,decoding:|control|row_spec_controlled(control),encoding:|control|row_spec_controlled(control)}}
#[test]
fn ieee_payload_actual_native_pack_bytes_agree_with_independent_dataview_and_sqlite(){let words=words64();oracle(&os_pack::encode_record_body(&spec(),&record(&words),&EncodeOptions::default()).unwrap(),&words);}
#[test]
fn ieee_payload_table_columns_preserve_all_words_in_binary_and_text(){let words=words64();let spec=RecordSpec::new(None,RecordLayout::Lines,vec![FieldSpec::new(1,"rows",Shape::Table(row_spec_producer()))]);let mut input=RecordValue::default();input.fields.insert(1,FieldValue::List(words.iter().map(|word|{let mut row=RecordValue::default();row.fields.insert(1,FieldValue::Float(f64::from_bits(*word)));FieldValue::Record(row)}).collect()));let body=os_pack::encode_record_body(&spec,&input,&EncodeOptions::default()).unwrap();oracle(&body,&words);let(restored,_)=os_pack::decode_record_body(&body,&spec,&DecodeOptions::default()).unwrap();let text=os_dsl::print(&input,&spec,JoinMode::Document);for restored in [restored,os_dsl::parse(&text,&spec,&ParseOptions::default()).unwrap()]{let FieldValue::List(rows)=restored.get(1).unwrap()else{panic!("expected table")};assert_eq!(rows.iter().map(|row|{let FieldValue::Record(row)=row else{panic!("expected row")};float(row.get(1).unwrap()).to_bits()}).collect::<Vec<_>>(),words);}}
#[test]
fn ieee_payload_coordinates_and_glued_units_preserve_words_and_reject_incompatible_dimensions(){let spec=RecordSpec::new(None,RecordLayout::Lines,vec![FieldSpec::new(1,"position",Shape::Coord(3)),FieldSpec::new(2,"quantity",Shape::Quantity(os_dsl::unit_by_symbol("GPa").unwrap()))]);for word in words64(){let mut input=RecordValue::default();input.fields.insert(1,FieldValue::Tuple(vec![FieldValue::Float(f64::from_bits(word)),FieldValue::Float(-0.0),FieldValue::Float(1.25)]));input.fields.insert(2,FieldValue::Float(f64::from_bits(word)));let text=os_dsl::print(&input,&spec,JoinMode::Document);let restored=os_dsl::parse(&text,&spec,&ParseOptions::default()).unwrap();assert_eq!(float(restored.get(2).unwrap()).to_bits(),word);let FieldValue::Tuple(position)=restored.get(1).unwrap()else{panic!("expected coordinate")};assert_eq!(float(&position[0]).to_bits(),word);assert_eq!(float(&position[1]).to_bits(),(-0.0_f64).to_bits());if f64::from_bits(word).is_nan(){let compatible=text.replace("GPa","MPa");assert_eq!(float(os_dsl::parse(&compatible,&spec,&ParseOptions::default()).unwrap().get(2).unwrap()).to_bits(),word);assert!(os_dsl::parse(&text.replace("GPa","m"),&spec,&ParseOptions::default()).is_err());}}}
fn witness_view(word:&u64)->Result<os_pack::ScalarRecordView<'_>,&'static str>{Ok(os_pack::ScalarRecordView{ordinal:0,fields:[Some(os_pack::ScalarRecordField::F64(f64::from_bits(*word))),None,None]})}
#[test]
fn ieee_payload_scalar_witness_accepts_each_exact_word_and_rejects_changed_payload(){use std::sync::Arc;for word in words64(){let root=Arc::new(word);let mut witness=os_pack::ScalarRecordWireWitness::new(root.clone(),witness_view);let mut bytes=vec![1,0,0,1,0,5];bytes.extend(word.to_le_bytes());let mut offset=0;let mut complete=false;for _ in 0..128{match witness.advance(bytes.get(offset).copied()).unwrap(){os_pack::ScalarRecordWireStep::Consumed{..}=>offset+=1,os_pack::ScalarRecordWireStep::Complete=>{complete=true;break;},os_pack::ScalarRecordWireStep::Progress{..}=>{}}}assert!(complete);assert_eq!(offset,bytes.len());witness.begin_close();assert!(Arc::ptr_eq(&witness.take_root().unwrap(),&root));assert!(witness.terminal_is_empty());let mut witness=os_pack::ScalarRecordWireWitness::new(root.clone(),witness_view);bytes[6]^=1;let mut offset=0;let mut failed=false;for _ in 0..128{match witness.advance(bytes.get(offset).copied()){Err(_)=>{failed=true;break;},Ok(os_pack::ScalarRecordWireStep::Consumed{..})=>offset+=1,Ok(os_pack::ScalarRecordWireStep::Complete)=>break,Ok(os_pack::ScalarRecordWireStep::Progress{..})=>{}}}assert!(failed);witness.begin_close();assert!(Arc::ptr_eq(&witness.take_root().unwrap(),&root));assert!(witness.terminal_is_empty());}}
